using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
internal static class SessionWorkspaceTests {
 public static void Run(){
  var previous=SynchronizationContext.Current; using(var context=new WindowsFormsSynchronizationContext()){ SynchronizationContext.SetSynchronizationContext(context); try{
  var global=new RelayConfiguration("first.example.test",8443,RelayTls.DefaultPin);DeviceEndpoint attempted=null;int calls=0,workers=0;bool block=false;var entered=new ManualResetEventSlim();var release=new ManualResetEventSlim();
  using(var workspace=new SessionWorkspace(()=>global,(endpoint,device,password,command,seconds,bytes,cancel)=>{Interlocked.Increment(ref calls);attempted=endpoint;if(block){Interlocked.Increment(ref workers);entered.Set();WaitHandle.WaitAny(new[]{release.WaitHandle,cancel.WaitHandle},5000);cancel.ThrowIfCancellationRequested();}return new CommandResult{ExitCode=0,Stdout=device.DeviceId};},message=>{global=new RelayConfiguration("next.example.test",9443,RelayTls.DefaultPin);return true;})){
   var a=new DeviceRecord{DisplayName="One",DeviceId="111222333",UseDefaultRelay=true};var connect=workspace.ConnectAsync(a,()=>"synthetic-a");Pump(connect);var one=connect.Result;
   Check(workspace.Sessions.Count==1&&attempted.Host=="first.example.test","successful checked tab uses confirmed immutable endpoint");a.DisplayName="Mutated";Check(one.Target.DisplayName=="One","tab target cloned");
   global=new RelayConfiguration("",0);var focused=workspace.ConnectAsync(one.Target,()=>{throw new Exception("existing record must not prompt");});Check(focused.Result==one,"same RecordId focuses unchanged tab even when new global configuration is invalid");global=new RelayConfiguration("first.example.test",8443,RelayTls.DefaultPin);var alias=new DeviceRecord{DisplayName="Quick alias",DeviceId="111222333",Host="first.example.test",Port=8443,Pin=RelayTls.DefaultPin};var duplicate=workspace.ConnectAsync(alias,()=>{throw new Exception("duplicate must not prompt credential");});Pump(duplicate);Check(duplicate.Result==one&&calls==1,"Quick/saved actual target deduplicated");
   var b=new DeviceRecord{DisplayName="Two",DeviceId="444555666",Host="custom.example.test",Port=8443,Pin=RelayTls.DefaultPin};var second=workspace.ConnectAsync(b,()=>"synthetic-b");Pump(second);var two=second.Result;
   block=true;entered.Reset();var run=workspace.RunAsync(one,"echo one",30,1024);PumpUntil(()=>entered.IsSet);Check(one.IsBusy&&!two.IsBusy,"independent operation state");
   var concurrent=workspace.RunAsync(two,"echo two",30,1024);PumpUntil(()=>Volatile.Read(ref workers)==2);Check(two.IsBusy,"different targets actually enter command providers concurrently");
   try{workspace.Close(one,false);throw new Exception("Expected active close confirmation");}catch(InvalidOperationException){Check(!one.IsClosed&&one.HasCredential,"Keep open preserves active tab/credential until explicit close approval");}
   var otherAlias=new DeviceRecord{DisplayName="Alias endpoint",DeviceId="111222333",Host="another.example.test",Port=9443,Pin=RelayTls.DefaultPin};try{workspace.ConnectAsync(otherAlias,()=>"synthetic-alias");throw new Exception("Expected same-ID gate");}catch(InvalidOperationException ex){Check(ex.Message.Contains("already running"),"same-ID alias gate");}
   workspace.Close(one,true);Check(one.IsClosed&&!one.HasCredential,"active close clears secret");release.Set();Pump(run);Pump(concurrent);Check(two.History.Count>=2&&two.Result.Stdout==b.DeviceId,"other session keeps its own output/history");
   workspace.Close(two,false);Check(!two.HasCredential&&workspace.Sessions.Count==0,"idle tab close releases state");
  }
  using(var failing=new SessionWorkspace(()=>global,(e,d,p,c,s,l,t)=>new CommandResult{ExitCode=7,Stderr="denied"},_=>true)){var failed=failing.ConnectAsync(new DeviceRecord{DisplayName="Failed",DeviceId="111222333",UseDefaultRelay=true},()=>"synthetic");PumpFailure(failed,"check failed");Check(failing.Sessions.Count==0,"failed identity never adds checked tab");}
  using(var empty=new SessionWorkspace(()=>global,(e,d,p,c,s,l,t)=>new CommandResult{ExitCode=0},_=>true)){var failed=empty.ConnectAsync(new DeviceRecord{DisplayName="Empty",DeviceId="111222333",UseDefaultRelay=true},()=>"synthetic");PumpFailure(failed,"no identity output");Check(empty.Sessions.Count==0,"empty identity never adds checked tab");}
  int failureCalls=0;using(var unknown=new SessionWorkspace(()=>global,(e,d,p,c,s,l,t)=>{failureCalls++;if(c!="hostname & whoami")throw new IOException("Result unknown after dispatch");return new CommandResult{Stdout="DEMO-PC\\demo"};},_=>true)){var target=unknown.ConnectAsync(new DeviceRecord{DisplayName="Unknown",DeviceId="111222333",UseDefaultRelay=true},()=>"synthetic");Pump(target);var run=unknown.RunAsync(target.Result,"echo once",30,1024);Pump(run);Check(failureCalls==2&&target.Result.Result==null&&target.Result.History.Count==2&&target.Result.History[1].Outcome.Contains("unknown"),"error-after-dispatch is recorded once, no replay or fabricated result");}
  var history=new RemoteSession(new DeviceRecord{DisplayName="Bounded",DeviceId="111222333",UseDefaultRelay=true},new DeviceEndpoint("relay.example.test",8443),"bounded","synthetic");for(int i=0;i<25;i++)history.Record("attempt "+i,new CommandResult{Stdout="small"});Check(history.History.Count==20&&history.History[0].Command=="attempt 5"&&history.HistoryEvicted,"20 attempts evicts oldest and discloses removal");history.History.Clear();for(int i=0;i<9;i++)history.Record("large "+i,new CommandResult{Stdout=new string('x',1048576)});Check(history.History.Count==8&&history.History[0].Command=="large 1"&&history.History[7].Command=="large 8","8MiB output limit retains latest and evicts oldest");history.RecordFailure("cancelled","Cancelled: remote result unknown");Check(history.Result==null&&history.History[history.History.Count-1].Result==null,"unknown attempt history never fabricates result/exit code");history.Clear();
  Console.WriteLine("PASS session isolation/dedup/parallel-targets/same-device gate/confirmation/close-secrets/history bounds"); }finally{SynchronizationContext.SetSynchronizationContext(previous);}}
 }
 static void Pump(Task task){PumpUntil(()=>task.IsCompleted);task.GetAwaiter().GetResult();}
 static void PumpFailure(Task task,string text){PumpUntil(()=>task.IsCompleted);try{task.GetAwaiter().GetResult();}catch(Exception ex){Check(ex.Message.Contains(text),"expected failure "+text);return;}throw new Exception("Expected session failure");}
 static void PumpUntil(Func<bool> done){var watch=System.Diagnostics.Stopwatch.StartNew();while(!done()&&watch.ElapsedMilliseconds<6000){Application.DoEvents();Thread.Sleep(10);}Check(done(),"bounded operation");}
 static void Check(bool value,string text){if(!value)throw new Exception("SessionWorkspaceTests: "+text);}
}
